// n8n turns a JSON array response into ONE ITEM PER ROW. So the rows of a
// PostgREST query are $('Node').all().map(i => i.json) - NOT
// $('Node').first().json, which returns only the first row's object.
//
// The previous version used .first().json everywhere and then indexed or
// .reduce()'d it as if it were an array. The effect: "stale_book" and
// "stale_forecast" fired on EVERY run regardless of freshness, failed ingest
// jobs and anomalies were never reported at all, and the volume check threw
// and reported itself as a failure. A watchdog that always cries wolf and
// never sees the wolf is worse than no watchdog.
//
// alwaysOutputData means a query with no rows still yields one item with an
// empty object, so empties are filtered out rather than counted as rows.
const rowsOf = (name) => $(name).all()
  .map(i => i.json)
  .filter(r => r && typeof r === 'object' && Object.keys(r).length > 0);

const now = Date.now();
const failures = [];
const context_notes = [];
const checks = {};

// --- book freshness ---------------------------------------------------
const bookRows = rowsOf('Check: latest book_snapshot');
const bookRow = bookRows[0];
if (bookRow?.observed_at) {
  const ageMin = (now - new Date(bookRow.observed_at).getTime()) / 60000;
  checks.book_age_min = Number(ageMin.toFixed(0));
  if (ageMin > 60) failures.push(`stale_book: ${ageMin.toFixed(0)}min old`);
} else {
  failures.push('stale_book: book_snapshots returned no rows at all');
}

// --- forecast freshness -----------------------------------------------
const fcRows = rowsOf('Check: latest forecast run');
const fcRow = fcRows[0];
if (fcRow?.run_at) {
  const ageH = (now - new Date(fcRow.run_at).getTime()) / 3600000;
  checks.forecast_age_h = Number(ageH.toFixed(1));
  if (ageH > 12) failures.push(`stale_forecast: ${ageH.toFixed(1)}h old`);
} else {
  failures.push('stale_forecast: weather_forecasts returned no rows at all');
}

// --- failed ingest jobs in the last 24h -------------------------------
const errRows = rowsOf('Check: failed ingest jobs (24h)')
  .filter(r => r.logged_at && (now - new Date(r.logged_at).getTime()) < 24 * 3600000);
checks.failed_jobs_24h = errRows.length;
if (errRows.length) {
  const jobs = [...new Set(errRows.map(r => r.job).filter(Boolean))];
  failures.push(`${errRows.length} failed ingest job(s) in 24h: ${jobs.join(', ')}`);
}

// --- anomalies in the last 24h ----------------------------------------
const anomRows = rowsOf('Check: anomalies (24h)')
  .filter(r => r.detected_at && (now - new Date(r.detected_at).getTime()) < 24 * 3600000);
checks.anomalies_24h = anomRows.length;
if (anomRows.length) failures.push(`${anomRows.length} anomaly row(s) in 24h`);

// n8n's own execution count cannot be read via Supabase - check it against
// n8n's Insights page; not automated here (docs/n8n_workflows.md).

// --- market volume ----------------------------------------------------
// A desk with live books and zero traded volume is not a working desk:
// either the trade ingest has stopped, or every market really has gone
// quiet. Both need telling, and neither shows up above - book_snapshots
// keeps updating either way.
const volRows = rowsOf('Check: traded volume (24h)');
const totalVol = volRows.reduce((s, r) => s + Number(r.volume_usd || 0), 0);
const totalTrades = volRows.reduce((s, r) => s + Number(r.n_trades || 0), 0);
checks.volume_usd_24h = Number(totalVol.toFixed(0));
checks.trades_24h = totalTrades;
checks.cities_with_volume = volRows.length;

if (volRows.length === 0) {
  failures.push('no_market_volume: v_city_volume returned no rows - trades_observed is empty or the trade ingest has stopped');
} else if (totalVol === 0) {
  failures.push('no_market_volume: $0 traded across all cities in the last 24h');
}
// Reported either way, so a clean run still tells you the size of the
// market you are trading into.
context_notes.push(
  `market volume 24h: $${totalVol.toFixed(0)} across ${volRows.length} cities, ${totalTrades} trades`);

return [{ json: {
  has_failures: failures.length > 0,
  failures, context_notes, checks,
  checked_at: new Date().toISOString(),
} }];

const r = $('Evaluate Thresholds').first().json;
const failures = r.failures || [];
const summary = r.has_failures
  ? `AD4 P4.1: ${failures.length} check(s) FAILED - email sent.`
  : 'AD4 P4.1: all clear.';
return [{ json: {
  summary,
  status: r.has_failures ? 'error' : 'ok',
  rows: failures.length,
  log: {
    p_job: 'P4.1_health_watchdog',
    p_status: r.has_failures ? 'error' : 'ok',
    p_rows: failures.length,
    p_detail: {
      summary,
      failures,
      checks: r.checks ?? null,
      trigger: $execution.mode,
      execution_id: $execution.id,
    },
  },
} }];

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE.
// should_run is granted to service_role and revoked from anon, so 42501 here
// is proof the Config node holds the anon key - and every write below would be
// refused too, silently, because the write nodes continue on error. Failing
// open on this particular answer is what let a whole run look healthy while
// writing nothing. Stop on the first node that can prove it.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). This is the ANON ` +
    `key in the Config node, not the service key - anon is granted SELECT and nothing else. ` +
    `Every write in this workflow would be refused the same way. Open Config -> service_key ` +
    `and paste the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or ` +
    `a key beginning sb_secret_). NEVER put that key anywhere starting NEXT_PUBLIC_.`);
}

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE.
// should_run is granted to service_role and revoked from anon, so 42501 here
// is proof the Config node holds the anon key - and every write below would be
// refused too, silently, because the write nodes continue on error. Failing
// open on this particular answer is what let a whole run look healthy while
// writing nothing. Stop on the first node that can prove it.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). This is the ANON ` +
    `key in the Config node, not the service key - anon is granted SELECT and nothing else. ` +
    `Every write in this workflow would be refused the same way. Open Config -> service_key ` +
    `and paste the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or ` +
    `a key beginning sb_secret_). NEVER put that key anywhere starting NEXT_PUBLIC_.`);
}

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;
